import os, re
def imports(m):
    p = m.replace('.', '/') + '.lean'
    return re.findall(r'^import\s+(AlgebraicJacobian[\w.]*)', open(p).read(), re.M) if os.path.exists(p) else []
for seed in ['AlgebraicJacobian.Jacobian','AlgebraicJacobian']:
    seen, stack = set(), [seed]
    while stack:
        m = stack.pop()
        if m not in seen:
            seen.add(m); stack += imports(m)
    total = sum(1 for _,_,fs in os.walk('AlgebraicJacobian') for f in fs if f.endswith('.lean'))
    print(f'{seed}: {len(seen)} of {total} modules reachable')
    if seed=='AlgebraicJacobian': root=seen
    else: hl=seen
disk={os.path.join(r,f).replace('./','').replace('/','.')[:-5] for r,_,fs in os.walk('AlgebraicJacobian') for f in fs if f.endswith('.lean')}
print('unrooted (on disk but not reachable from AlgebraicJacobian):', len(disk-root))
for x in sorted(disk-root)[:10]: print('  ',x)
